input.function:
() => {
  const r = {};
  r.fontLoaded = document.fonts.check('700 62px Inter');
  const card = document.querySelector('.card');
  const cb = card.getBoundingClientRect();
  r.card = [cb.width, cb.height];
  const inner = document.getElementById('root');
  r.innerScroll = [inner.scrollWidth, inner.scrollHeight, inner.clientWidth, inner.clientHeight];
  r.items = [...document.querySelectorAll('.brand,.accentbar,.title,.speaker,.meta,.cta,.avatar')].map(e=>{
    const b=e.getBoundingClientRect();
    return [e.className, Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)];
  });
  const t = document.querySelector('.title');
  r.titleLines = Math.round(t.getBoundingClientRect().height / parseFloat(getComputedStyle(t).lineHeight));
  return r;
}

